import math, subprocess, os
W,H=800,600
N=90
proc=subprocess.Popen(['ffmpeg','-y','-f','rawvideo','-pix_fmt','rgb24','-s',f'{W}x{H}','-r','30','-i','-','-pix_fmt','yuv420p','-crf','20','output/pelican-ride.mp4'],stdin=subprocess.PIPE,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
def rect(px, x0,y0,x1,y1,c):
  for y in range(max(0,y0),min(H,y1)):
    for x in range(max(0,x0),min(W,x1)):
      px[y*W+x]=c
def circle(px,cx,cy,r,c):
  for y in range(int(cy-r),int(cy+r)+1):
    for x in range(int(cx-r),int(cx+r)+1):
      if 0<=x<W and 0<=y<H and (x-cx)**2+(y-cy)**2<=r*r: px[y*W+x]=c
def ellipse(px,cx,cy,rx,ry,c):
  for y in range(int(cy-ry),int(cy+ry)+1):
    for x in range(int(cx-rx),int(cx+rx)+1):
      if 0<=x<W and 0<=y<H and ((x-cx)/rx)**2+((y-cy)/ry)**2<=1: px[y*W+x]=c
for f in range(N):
  px=[(126,200,227)]*(W*H)
  bob=int(8*math.sin(2*math.pi*f/N))
  # sea & walk
  rect(px,0,380,W,600,(40,150,190)); rect(px,0,400,W,510,(217,160,102))
  off=(f*8)%80
  for x in range(-80,W,80):
    for y in range(412,510):
      px[y*W+((x+off)%W)]=(170,110,60)
  # sun
  circle(px,640,110,48,(255,223,93))
  # board
  ellipse(px,410,523,175,14,(0,0,0))
  ellipse(px,410+bob//2,455+bob,205,14,(200,40,80))
  circle(px,279,500,26,(30,30,30)); circle(px,279,500,14,(255,210,63))
  circle(px,529,500,26,(30,30,30)); circle(px,529,500,14,(255,210,63))
  # body
  ellipse(px,380,360+bob,130,90,(245,245,245))
  ellipse(px,300,330+bob,90,40,(180,195,205))  # wing
  ellipse(px,515,190+bob,48,48,(245,245,245))  # head
  circle(px,531,183+bob,6,(20,20,20))
  # beak
  for i in range(135):
    t=i/135
    for dy in range(-8,14):
      x=int(555+t*135); y=int((178+t*42)+bob+dy*(1-t*0.5))
      if 0<=x<W and 0<=y<H: px[y*W+x]=(240,144,26) if dy<2 else (242,112,89)
  data=bytearray()
  for (r,g,b) in px: data+=bytes((r,g,b))
  proc.stdin.write(data)
proc.stdin.close(); proc.wait()
print("done")
